export interface FemaleCauseCard {
  id: string;
  icon: React.ReactNode;
  title: string;
  description: string;
}

const defaultCauses: FemaleCauseCard[] = [
  {
    id: "shock-loss",
    icon: <DecliningChartIcon />,
    title: "Shock loss",
    description:
      "The temporary loss of transplanted and surrounding natural hair that occurs as a result of surgical injury (called shock in this case).",
  },
  {
    id: "poor-aftercare",
    icon: <PoorAftercareIcon />,
    title: "Poor Aftercare",
    description:
      "Neglecting instructions such as post-operation instructions may influence growth.",
  },
  {
    id: "hormonal-imbalance",
    icon: <DnaHelixIcon />,
    title: "Hormonal Imbalance",
    description:
      "Conditions, such as PCOS or thyroid diseases influence outcomes.",
  },
  {
    id: "inexperienced-clinic",
    icon: <UserScalpelIcon />,
    title: "Inexperienced Clinic/ Surgeon",
    description:
      "The lack of experience may result in unsuccessful grafts.",
  },
  {
    id: "nutritional-deficiencies",
    icon: <NutritionalDeficienciesIcon />,
    title: "Nutritional Deficiencies",
    description:
      "Hair decline may be caused by a shortage of proteins, iron or vitamins.",
  },
];

export interface FemaleCausesProps {
  titleLine1?: string;
  titleLine2?: string;
  subtitle?: string;
  causes?: FemaleCauseCard[];
}

export default function FemaleCausesOfHairLoss({
  titleLine1 = "Causes of Hair Loss Leading to",
  titleLine2 = "FEMALE hair transplant",
  subtitle = "Understanding the early causes of ultra-dense hair transplant loss can help in identifying the underlying factors that contribute to poor graft survival rates.",
  causes = defaultCauses,
}: FemaleCausesProps) {
  const topRow = causes.slice(0, 3);
  const bottomRow = causes.slice(3);

  return (
    <section className="w-full bg-white py-14 sm:py-20 lg:py-24 overflow-hidden">
      <div className="max-w-[1240px] mx-auto px-4 sm:px-6 lg:px-8">
        {/* ── Section Header (centered) ── */}
        <div className="text-center max-w-[840px] mx-auto mb-12 sm:mb-16 lg:mb-20">
          <h2 className="font-['Plus_Jakarta_Sans'] text-[26px] sm:text-[36px] lg:text-[44px] font-extrabold tracking-[-0.03em] leading-[1.18]">
            <span className="text-[#001e56] block">{titleLine1}</span>
            <span className="text-[#00A3FF] block mt-1">{titleLine2}</span>
          </h2>
          <p className="mt-4 sm:mt-5 text-[#556987] font-['Plus_Jakarta_Sans'] text-[14px] sm:text-[15.5px] leading-[1.7] font-normal max-w-[700px] mx-auto">
            {subtitle}
          </p>
        </div>

        {/* ── Top Row: 3 Cards ── */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 sm:gap-7 mb-6 sm:mb-7 max-w-[1060px] mx-auto">
          {topRow.map((cause) => (
            <div
              key={cause.id}
              className="group relative flex flex-col justify-start rounded-[26px] sm:rounded-[32px] bg-[#eef3f8] border border-[#dce8f2] p-6 sm:p-8 transition-all duration-300 hover:shadow-[0_12px_32px_rgba(3,30,80,0.09)] hover:-translate-y-0.5"
            >
              {/* Icon container */}
              <div className="mb-5 sm:mb-6 shrink-0 flex items-center justify-start h-[60px]">
                {cause.icon}
              </div>

              {/* Title */}
              <h3 className="font-['Plus_Jakarta_Sans'] text-[17px] sm:text-[18px] lg:text-[19px] font-bold text-[#001e56] mb-2.5 sm:mb-3 tracking-[-0.01em] leading-snug">
                {cause.title}
              </h3>

              {/* Description */}
              <p className="font-['Plus_Jakarta_Sans'] text-[13px] sm:text-[13.5px] leading-[1.65] text-[#556987] font-normal">
                {cause.description}
              </p>
            </div>
          ))}
        </div>

        {/* ── Bottom Row: 2 Cards (centered) ── */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 sm:gap-7 max-w-[720px] mx-auto">
          {bottomRow.map((cause) => (
            <div
              key={cause.id}
              className="group relative flex flex-col justify-start rounded-[26px] sm:rounded-[32px] bg-[#eef3f8] border border-[#dce8f2] p-6 sm:p-8 transition-all duration-300 hover:shadow-[0_12px_32px_rgba(3,30,80,0.09)] hover:-translate-y-0.5"
            >
              {/* Icon container */}
              <div className="mb-5 sm:mb-6 shrink-0 flex items-center justify-start h-[60px]">
                {cause.icon}
              </div>

              {/* Title */}
              <h3 className="font-['Plus_Jakarta_Sans'] text-[17px] sm:text-[18px] lg:text-[19px] font-bold text-[#001e56] mb-2.5 sm:mb-3 tracking-[-0.01em] leading-snug">
                {cause.title}
              </h3>

              {/* Description */}
              <p className="font-['Plus_Jakarta_Sans'] text-[13px] sm:text-[13.5px] leading-[1.65] text-[#556987] font-normal">
                {cause.description}
              </p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
